<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/public-discovery.php';require_once __DIR__.'/app/annotation-ui.php';$u=require_user($pdo);$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$action=(string)($_POST['action']??'');if($action==='create_collection'){$title=trim((string)($_POST['title']??''));if($title==='')$error='Collection title is required.';else{$visibility=in_array($_POST['visibility']??'private',['private','public'],true)?$_POST['visibility']:'private';$pdo->prepare('INSERT INTO collections(public_id,owner_user_id,title,description,visibility) VALUES(?,?,?,?,?)')->execute([ulid_like(),$u['id'],$title,trim((string)($_POST['description']??''))?:null,$visibility]);$success='Collection created.';}}if($action==='add_to_collection'){$collection=(string)($_POST['collection']??'');$annotation=(string)($_POST['annotation']??'');$q=$pdo->prepare('SELECT id FROM collections WHERE public_id=? AND owner_user_id=?');$q->execute([$collection,$u['id']]);$cid=(int)($q->fetchColumn()?:0);$access=annotation_access($pdo,$annotation,$u);$aid=(int)($access['id']??0);if($cid&&$aid){$pdo->prepare('INSERT IGNORE INTO collection_items(collection_id,annotation_id,added_by_user_id) VALUES(?,?,?)')->execute([$cid,$aid,$u['id']]);$success='Added to collection.';}else$error='Unable to add that annotation.';}if($action==='remove_saved'){$annotation=(string)($_POST['annotation']??'');$q=$pdo->prepare('DELETE sa FROM saved_annotations sa JOIN annotations a ON a.id=sa.annotation_id WHERE sa.user_id=? AND a.public_id=?');$q->execute([$u['id'],$annotation]);$success='Removed from Saved.';}}
$q=$pdo->prepare("SELECT a.public_id FROM saved_annotations sa JOIN annotations a ON a.id=sa.annotation_id WHERE sa.user_id=? ORDER BY sa.created_at DESC");$q->execute([$u['id']]);$saved=[];foreach($q->fetchAll(PDO::FETCH_COLUMN) as $aid){$row=public_discovery_annotation($pdo,(string)$aid,$u);if($row)$saved[]=$row;}$q=$pdo->prepare('SELECT public_id,title,description,visibility,updated_at FROM collections WHERE owner_user_id=? ORDER BY updated_at DESC');$q->execute([$u['id']]);$collections=$q->fetchAll();$selected=null;$items=[];if(!empty($_GET['collection'])){$q=$pdo->prepare('SELECT * FROM collections WHERE public_id=? AND owner_user_id=?');$q->execute([(string)$_GET['collection'],$u['id']]);$selected=$q->fetch();if($selected){$q=$pdo->prepare("SELECT a.public_id FROM collection_items ci JOIN annotations a ON a.id=ci.annotation_id WHERE ci.collection_id=? ORDER BY ci.created_at DESC");$q->execute([$selected['id']]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $aid){$row=public_discovery_annotation($pdo,(string)$aid,$u);if($row)$items[]=$row;}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Saved · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/home.php">Home</a><a href="/explore.php">Explore</a><a href="/search.php">Search</a><a href="/settings.php">Settings</a></nav></header><main class="layout"><section><div class="pageTitle"><div class="eyebrow">LIBRARY</div><h1><?=$selected?h($selected['title']):'Saved'?></h1><?php if($selected&&$selected['description']):?><p><?=h($selected['description'])?></p><?php endif?></div><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php $rows=$selected?$items:$saved;if(!$rows):?><div class="card">Nothing here yet.</div><?php endif?><?php foreach($rows as $a):?><?=annotation_ui_card($a,$u)?><?php if(!$selected&&$collections):?><form method="post" class="inlineForm savedCollectionAction"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add_to_collection"><input type="hidden" name="annotation" value="<?=h($a['public_id'])?>"><select name="collection"><?php foreach($collections as $c):?><option value="<?=h($c['public_id'])?>"><?=h($c['title'])?></option><?php endforeach?></select><button class="button secondary">Add to collection</button></form><?php endif?><?php endforeach?></section><aside><div class="card"><h3>Collections</h3><?php foreach($collections as $c):?><p><a href="/saved.php?collection=<?=h($c['public_id'])?>"><?=h($c['title'])?></a><br><span class="meta"><?=h($c['visibility'])?><?php if($c['visibility']==='public'):?> · <a href="/collection.php?id=<?=h($c['public_id'])?>">public view</a><?php endif?></span></p><?php endforeach?></div><div class="card"><h3>New collection</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_collection"><label>Title<input name="title" required></label><label>Description<textarea name="description" rows="3"></textarea></label><label>Visibility<select name="visibility"><option value="private">Private</option><option value="public">Public</option></select></label><button>Create</button></form></div></aside></main><?=annotation_ui_scripts($u)?></body></html>
